#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> sortByAbsoluteValue(vector<int>& nums) {
        stable_sort(nums.begin(), nums.end(), [](int a, int b) {
            return abs(static_cast<long long>(a)) < abs(static_cast<long long>(b));
        });
        return nums;
    }
};
